import csv
import io

def report(rows):
    return [{'id':r['id'],'refund_cents':r.get('refund_cents')} for r in rows]

def download(rows):
    result=io.StringIO()
    writer=csv.writer(result)
    writer.writerow(['ID','Refund cents'])
    for row in report(rows):
        writer.writerow([row['id'],str(row['refund_cents'])])
    return result.getvalue()

